+// API keys and roles. A key is { key, name, role }; viewers read, cooks also
+// do kitchen work, managers do everything.
+const COOK_ROUTES = [
+  /^\/recipes\/[^/]+\/cook$/,
+  /^\/batches\/[^/]+\/waste$/,
+  /^\/temperatures$/,
+  /^\/stocktakes\/[^/]+\/counts$/,
+];
+
+/** The api key record for an `Authorization: Bearer <key>` header, or null. */
+export function authenticate(store, header) {
+  const m = /^Bearer (.+)$/.exec(header ?? "");
+  if (!m) return null;
+  return (store.data.apiKeys ?? []).find((k) => k.key === m[1]) ?? null;
+}
+
+/** Whether `role` may make a request with `method` to `path`. */
+export function allowed(role, method, path) {
+  if (role === "manager") return true;
+  if (path === "/audit") return false;
+  if (method === "GET") return role === "viewer" || role === "cook";
+  return role === "cook" && method === "POST" && COOK_ROUTES.some((re) => re.test(path));
+}
