@@ -0,0 +1,12 @@
+// The audit trail: one entry for every request that changes data.
+
+/** Appends an audit entry { at, name, method, path, status }. */
+export function recordAudit(store, { at, name, method, path, status }) {
+  store.data.audit ??= [];
+  store.data.audit.push({ at, name, method, path, status });
+}
+
+/** All audit entries, newest first. */
+export function listAudit(store) {
+  return [...(store.data.audit ?? [])].reverse();
+}
